// PATCH(amend-2026-08-07: add canvas support) — the spec carries no canvas
// endpoints, so the generator emitted no commands for Slack canvases at all.
// The whole surface is hand-added here.
//
// Unlike the generated layout (one file per command), this keeps the resource in
// one file behind a shared postCanvas helper. Six near-identical copies of the
// client/error/envelope boilerplate would be harder to review and to keep
// consistent, and since no template produces these commands there is no
// generated output for a future reprint to diff against anyway.
//
// Requires the canvases:write and canvases:read user-token scopes. Without them
// Slack answers missing_scope, which checkSlackAPIError renders with the scope
// name and the reinstall hint.
//
// Contract established against the live API:
//
//	canvases.create              title, document_content{type,markdown} -> canvas_id
//	canvases.edit                canvas_id, changes[]{operation,document_content,section_id?}
//	canvases.delete              canvas_id
//	canvases.access.set          canvas_id, access_level, user_ids[]/channel_ids[]
//	canvases.sections.lookup     canvas_id, criteria{section_types[]} -> sections[]{id}
//	conversations.canvases.create channel_id, document_content (also works on DMs)
//
// Reading is the one operation with no dedicated endpoint. Slack exposes no
// "get canvas content" call and files.info carries no preview for a canvas, but
// a canvas is backed by a file, so files.info's url_private_download serves the
// body as HTML. That download DOES require the Authorization header — unlike the
// external file-upload URL, which must not carry it. Verified to work with a
// plain xoxp OAuth token and files:read; it does not need the browser-session
// (xoxc/xoxd) credentials some third-party tooling uses for this.

// --canvas is validated unconditionally, including under --dry-run. The
// generated commands gate required-flag checks on !dryRun so the request shape
// can be previewed without real ids, but for canvases that made --dry-run report
// success for a request carrying an empty canvas_id — hiding exactly the mistake
// the dry run was meant to catch.

// canvasDocument builds Slack's document_content payload from either inline
// markdown or a file. Returns an empty map when neither is set, which is valid
// for canvases.create (an untitled blank canvas).
func canvasDocument(content, contentFile string) (map[string]any, error) {
	if content != "" && contentFile != "" {
		return nil, usageErr(fmt.Errorf("--content and --content-file are mutually exclusive"))
	}
	markdown := content
	if contentFile != "" {
		b, err := os.ReadFile(contentFile)
		if err != nil {
			return nil, fmt.Errorf("reading --content-file: %w", err)
		}
		markdown = string(b)
	}
	if markdown == "" {
		return nil, nil
	}
	return map[string]any{"type": "markdown", "markdown": markdown}, nil
}

// postCanvas runs a canvas write and renders it the way the generated POST
// commands do, so output shape stays consistent across the CLI.
func postCanvas(cmd *cobra.Command, flags *rootFlags, path string, body map[string]any) error {
	c, err := flags.newClient()
	if err != nil {
		return err
	}
	data, statusCode, err := c.Post(cmd.Context(), path, body)
	if err != nil {
		return classifyAPIError(err, flags)
	}
	if slackErr := checkSlackAPIError(data); slackErr != nil {
		return slackErr
	}
	// --quiet is checked once, above both output branches, the way canvases read
	// does it. The terminal branch below already suppressed output — the guard
	// lives inside printOutputWithFlags — but with the only visible check nested
	// in the JSON branch, that suppression read as conditional on --json. One
	// guard here makes the contract local: past this point, quiet prints nothing.
	if flags.quiet {
		return nil
	}
	if flags.asJSON || !isTerminal(cmd.OutOrStdout()) {
		filtered := data
		if flags.compact {
			filtered = compactFields(filtered)
		}
		if flags.selectFields != "" {
			filtered = filterFields(filtered, flags.selectFields)
		}
		envelope := map[string]any{
			"action":   "post",
			"resource": "canvases",
			"path":     path,
			"status":   statusCode,
			"success":  statusCode >= 200 && statusCode < 300,
		}
		if flags.dryRun {
			envelope["dry_run"] = true
			envelope["status"] = 0
			envelope["success"] = false
		}
		if len(filtered) > 0 {
			var parsed any
			if err := json.Unmarshal(filtered, &parsed); err == nil {
				envelope["data"] = parsed
			}
		}
		envelopeJSON, err := json.Marshal(envelope)
		if err != nil {
			return err
		}
		return printOutput(cmd.OutOrStdout(), json.RawMessage(envelopeJSON), true)
	}
	return printOutputWithFlags(cmd.OutOrStdout(), data, flags)
}

// splitIDs turns a comma-separated flag into a trimmed slice, dropping blanks so
// a trailing comma doesn't send an empty id.
func splitIDs(s string) []string {
	var out []string
	for _, p := range strings.Split(s, ",") {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	return out
}

