// canvasHTMLToText strips tags for a rough plain-text rendering. It is
// deliberately crude: it exists so `--format text` gives something greppable,
// not so it round-trips. Anything needing structure should read the HTML, which
// carries the section ids.
func canvasHTMLToText(html string) string {
	var b strings.Builder
	depth := 0
	for _, r := range html {
		switch {
		case r == '<':
			depth++
		case r == '>':
			if depth > 0 {
				depth--
			}
			// Tag boundaries are paragraph boundaries often enough that a
			// newline here reads better than running everything together.
			if depth == 0 {
				b.WriteRune('\n')
			}
		case depth == 0:
			b.WriteRune(r)
		}
	}
	// Collapse the runs of blank lines the naive approach above produces.
	lines := strings.Split(b.String(), "\n")
	var out []string
	for _, l := range lines {
		if l = strings.TrimSpace(l); l != "" {
			out = append(out, l)
		}
	}
	return strings.Join(out, "\n")
}

func newCanvasesReadCmd(flags *rootFlags) *cobra.Command {
	var flagCanvas, flagFormat string

	cmd := &cobra.Command{
		Use:   "read",
		Short: "Read a canvas's content",
		Long: "Read a canvas's content.\n\n" +
			"Slack has no get-canvas-content endpoint, so this resolves the canvas's backing\n" +
			"file via files.info and downloads url_private_download, which serves the body as\n" +
			"HTML. The HTML carries section ids inline, so unlike 'canvases sections' — which\n" +
			"returns ids only — this shows you which id goes with which content, which is what\n" +
			"you need to target an edit.\n\n" +
			"Requires files:read in addition to the canvas scopes.",
		Example: `  slack-pp-cli canvases read --canvas F0123456789
  slack-pp-cli canvases read --canvas F0123456789 --format text`,
		RunE: func(cmd *cobra.Command, args []string) error {
			if flagCanvas == "" {
				return usageErr(fmt.Errorf("required flag \"canvas\" not set"))
			}
			if flagFormat != "html" && flagFormat != "text" {
				return usageErr(fmt.Errorf("--format must be html or text, got %q", flagFormat))
			}
			c, err := flags.newClient()
			if err != nil {
				return err
			}

			// Reading is two requests against two hosts, so it needs its own
			// dry-run branch like files upload does. Without one, c.Get returns the
			// synthetic dry-run envelope, the code below parses that as a files.info
			// response, finds no download URL and fails — making --dry-run report an
			// error for a request that would have succeeded.
			if c.DryRun {
				// The quiet guard further down is only reached on the real read path,
				// so --dry-run --quiet printed the plan. Check it here too.
				if flags.quiet {
					return nil
				}
				plan := map[string]any{
					"dry_run": true,
					"steps": []map[string]any{
						{"step": 1, "method": "GET", "path": "/files.info", "file": flagCanvas},
						{"step": 2, "method": "GET", "path": "<url_private_download from step 1>", "authenticated": true, "format": flagFormat},
					},
				}
				planJSON, err := json.Marshal(plan)
				if err != nil {
					return err
				}
				return printOutput(cmd.OutOrStdout(), json.RawMessage(planJSON), true)
			}

			info, err := c.Get(cmd.Context(), "/files.info", map[string]string{"file": flagCanvas})
			if err != nil {
				return classifyAPIError(err, flags)
			}
			if slackErr := checkSlackAPIError(info); slackErr != nil {
				return slackErr
			}
			var meta struct {
				File struct {
					Title    string `json:"title"`
					Filetype string `json:"filetype"`
					Download string `json:"url_private_download"`
					Private  string `json:"url_private"`
				} `json:"file"`
			}
			if err := json.Unmarshal(info, &meta); err != nil {
				return fmt.Errorf("parsing files.info response: %w", err)
			}
			url := meta.File.Download
			if url == "" {
				url = meta.File.Private
			}
			if url == "" {
				return fmt.Errorf("files.info returned no download URL for %s; is it a canvas?", flagCanvas)
			}

			// This download needs the credential, unlike the upload URL in
			// files_upload.go which must not receive one.
			body, _, err := c.FetchRaw(cmd.Context(), url)
			if err != nil {
				return classifyAPIError(err, flags)
			}
			content := string(body)
			if flagFormat == "text" {
				content = canvasHTMLToText(content)
			}

			// --quiet asks for no output, and a canvas body is exactly the kind of
			// content a caller would not want landing in a script's stdout or a log.
			// Both branches below printed it regardless. Honour the flag; the fetch
			// still happens, so a read failure is still reported through the exit
			// code.
			if flags.quiet {
				return nil
			}
			if flags.asJSON {
				envelope := map[string]any{
					"resource":  "canvases",
					"canvas_id": flagCanvas,
					"title":     meta.File.Title,
					"format":    flagFormat,
					"content":   content,
				}
				envelopeJSON, err := json.Marshal(envelope)
				if err != nil {
					return err
				}
				return printOutput(cmd.OutOrStdout(), json.RawMessage(envelopeJSON), true)
			}
			fmt.Fprintln(cmd.OutOrStdout(), content)
			return nil
		},
	}
	cmd.Flags().StringVar(&flagCanvas, "canvas", "", "Canvas ID to read")
	cmd.Flags().StringVar(&flagFormat, "format", "html", "html (preserves section ids) or text")
	return cmd
}

func newCanvasesEditCmd(flags *rootFlags) *cobra.Command {
	var flagCanvas, flagContent, flagContentFile, flagOperation, flagSection string

	// Slack rejects anything outside this set; checking locally gives a better
	// message than a bare invalid_arguments.
	valid := map[string]bool{
		"insert_at_start": true, "insert_at_end": true,
		"insert_before": true, "insert_after": true,
		"replace": true, "delete": true,
	}

	cmd := &cobra.Command{
		Use:   "edit",
		Short: "Apply a change to an existing canvas",
		Long: "Apply one change to a canvas.\n\n" +
			"Operations: insert_at_start, insert_at_end, insert_before, insert_after, replace, delete.\n" +
			"The positional operations and replace/delete act on --section; find section ids with\n" +
			"'canvases sections'.",
		Example: `  slack-pp-cli canvases edit --canvas F0123456789 --content "## Status" --operation insert_at_end
  slack-pp-cli canvases edit --canvas F0123456789 --section temp:C:abc --operation delete`,
		RunE: func(cmd *cobra.Command, args []string) error {
			if flagCanvas == "" {
				return usageErr(fmt.Errorf("required flag \"canvas\" not set"))
			}
			if !valid[flagOperation] {
				return usageErr(fmt.Errorf("--operation %q is not one of insert_at_start, insert_at_end, insert_before, insert_after, replace, delete", flagOperation))
			}
			doc, err := canvasDocument(flagContent, flagContentFile)
			if err != nil {
				return err
			}
			if flagOperation == "delete" {
				if flagSection == "" {
					return usageErr(fmt.Errorf("--section is required for --operation delete"))
				}
				if doc != nil {
					return usageErr(fmt.Errorf("--operation delete takes no content"))
				}
			} else if doc == nil {
				return usageErr(fmt.Errorf("--content or --content-file is required for --operation %s", flagOperation))
			}
			if (flagOperation == "insert_before" || flagOperation == "insert_after" || flagOperation == "replace") && flagSection == "" {
				return usageErr(fmt.Errorf("--section is required for --operation %s", flagOperation))
			}

			change := map[string]any{"operation": flagOperation}
			if doc != nil {
				change["document_content"] = doc
			}
			if flagSection != "" {
				change["section_id"] = flagSection
			}
			return postCanvas(cmd, flags, "/canvases.edit", map[string]any{
				"canvas_id": flagCanvas,
				"changes":   []map[string]any{change},
			})
		},
	}
	cmd.Flags().StringVar(&flagCanvas, "canvas", "", "Canvas ID to edit")
	cmd.Flags().StringVar(&flagContent, "content", "", "Markdown content for the change")
	cmd.Flags().StringVar(&flagContentFile, "content-file", "", "Path to a Markdown file to use as the change content")
	cmd.Flags().StringVar(&flagOperation, "operation", "insert_at_end", "insert_at_start, insert_at_end, insert_before, insert_after, replace, or delete")
	cmd.Flags().StringVar(&flagSection, "section", "", "Section ID the operation targets (see 'canvases sections')")
	return cmd
}

