func newCanvasesAccessSetCmd(flags *rootFlags) *cobra.Command {
	var flagCanvas, flagAccessLevel, flagUsers, flagChannels string

	cmd := &cobra.Command{
		Use:   "access-set",
		Short: "Grant users or channels access to a canvas",
		Example: `  slack-pp-cli canvases access-set --canvas F0123456789 --access-level write --users U0123456789,U9876543210
  slack-pp-cli canvases access-set --canvas F0123456789 --access-level read --channels C0123456789`,
		RunE: func(cmd *cobra.Command, args []string) error {
			if flagCanvas == "" {
				return usageErr(fmt.Errorf("required flag \"canvas\" not set"))
			}
			if flagAccessLevel != "read" && flagAccessLevel != "write" {
				return usageErr(fmt.Errorf("--access-level must be read or write, got %q", flagAccessLevel))
			}
			users := splitIDs(flagUsers)
			channels := splitIDs(flagChannels)
			if len(users) == 0 && len(channels) == 0 {
				return usageErr(fmt.Errorf("one of --users or --channels is required"))
			}
			body := map[string]any{"canvas_id": flagCanvas, "access_level": flagAccessLevel}
			if len(users) > 0 {
				body["user_ids"] = users
			}
			if len(channels) > 0 {
				body["channel_ids"] = channels
			}
			return postCanvas(cmd, flags, "/canvases.access.set", body)
		},
	}
	cmd.Flags().StringVar(&flagCanvas, "canvas", "", "Canvas ID")
	cmd.Flags().StringVar(&flagAccessLevel, "access-level", "read", "read or write")
	cmd.Flags().StringVar(&flagUsers, "users", "", "Comma-separated user IDs to grant access to")
	cmd.Flags().StringVar(&flagChannels, "channels", "", "Comma-separated channel IDs to grant access to")
	return cmd
}

